function bridgeName(){return state.bridge==='stats'?'Statistics bridge · STATS 707 → 765':state.bridge==='cs'?'Computer science bridge · COMPSCI 717 + 751':'Bridging courses not recorded'}
function bridgeFocus(n){if(!['stats','cs'].includes(state.bridge)||n>12)return '';let r=bridgeResources[state.bridge][Math.min(2,Math.floor((n-1)/4))];return `<section class="panel" style="margin-top:17px"><span class="eyebrow">YOUR 240-POINT BRIDGE</span><h3 style="margin-top:8px">${esc(bridgeName())}</h3><p><b>Week ${n} focus:</b> ${esc(bridgeLessons[state.bridge][n-1])}. Use this within your weekly study hours.</p><a class="link" href="${esc(r[1])}" target="_blank" rel="noopener noreferrer">${esc(r[0])} ↗</a></section>`}
const defaults={done:{},topics:{},dsaDone:{},notes:{},missions:{},weekEvidence:{},skillLevels:{},skillEvidence:{},portfolio:{},portfolioLinks:{},start:'2026-10-12',hours:12,path:'240',bridge:'unknown',activity:{},timerSessions:[]};
const state=(()=>{try{return {...defaults,...JSON.parse(localStorage.getItem('study-compass-v2')||'{}')}}catch{return {...defaults}}})();
state.path='240';
for(const key of ['dsaDone','missions','weekEvidence','skillLevels','skillEvidence','portfolio','portfolioLinks','activity','timerSessions'])state[key]??={};
function save(){localStorage.setItem('study-compass-v2',JSON.stringify(state));updateSide()}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function weekDate(n){let d=new Date(state.start+'T12:00:00');d.setDate(d.getDate()+7*(n-1));return d}
function dateRange(n){const a=weekDate(n),b=new Date(a);b.setDate(a.getDate()+6);return a.toLocaleDateString('en-NZ',{day:'numeric',month:'short'})+' – '+b.toLocaleDateString('en-NZ',{day:'numeric',month:'short'})}
function currentWeek(){let now=new Date(),start=new Date(state.start+'T00:00:00');return Math.max(1,Math.min(24,Math.floor((now-start)/604800000)+1))}
function tasks(w){let arr=w.f.map(([tag,text],i)=>({id:`w${w.n}-t${i}`,tag,text}));arr.push({id:`w${w.n}-output`,tag:'DELIVERABLE',text:w.o});return arr}
function missionCount(w){return (missions[w.n-1]?.steps||[]).filter((_,i)=>state.missions[`${w.n}-${i}`]).length}
function weekTotal(w){return tasks(w).length}
function doneCount(w){return tasks(w).filter(t=>state.done[t.id]).length}
function percent(w){return Math.round(doneCount(w)/weekTotal(w)*100)}
function updateSide(){let n=data.weeks.slice(0,20).reduce((a,w)=>a+doneCount(w),0),total=data.weeks.slice(0,20).reduce((a,w)=>a+weekTotal(w),0),p=Math.round(n/total*100);$('#side-progress').textContent=p+'%';$('#side-bar').style.width=p+'%'}

/* ---------- Daily tracking helpers ---------- */
function todayKey(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function dayOffset(key,days){const d=new Date(key+'T12:00:00');d.setDate(d.getDate()+days);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function getActivity(key){return state.activity[key]||{minutes:0,tasks:[],missions:0}}
function setActivity(key,patch){state.activity[key]={...getActivity(key),...patch};save()}
function calcStreak(){let streak=0,key=todayKey();for(let i=0;i<400;i++){const a=state.activity[key];const active=a&&(a.minutes>0||(a.tasks&&a.tasks.length)||a.missions>0);if(!active){if(i===0){key=dayOffset(key,-1);continue}break}streak++;key=dayOffset(key,-1)}return streak}
function calcLongestStreak(){let best=0,cur=0;const keys=Object.keys(state.activity).sort();if(!keys.length)return 0;let prev=null;for(const k of keys){const a=state.activity[k];const active=a&&(a.minutes>0||(a.tasks&&a.tasks.length)||a.missions>0);if(!active)continue;if(prev&&dayOffset(prev,1)===k)cur++;else cur=1;best=Math.max(best,cur);prev=k}return best}
function logTaskToday(id){const k=todayKey(),a=getActivity(k);const tasks=[...new Set([...(a.tasks||[]),id])];setActivity(k,{tasks})}
function logMissionToday(){const k=todayKey(),a=getActivity(k);setActivity(k,{missions:(a.missions||0)+1})}
function logMinutesToday(mins){const k=todayKey(),a=getActivity(k);setActivity(k,{minutes:(a.minutes||0)+(mins||0)});state.timerSessions.push({date:k,minutes:mins,ts:Date.now()});if(state.timerSessions.length>500)state.timerSessions=state.timerSessions.slice(-500);save()}
function last7Days(){const arr=[];for(let i=6;i>=0;i--)arr.push(dayOffset(todayKey(),-i));return arr}

function weekCard(w){let p=percent(w);return `<button class="week-card ${w.n===currentWeek()?'current':''} ${p===100?'done':''}" data-week="${w.n}"><div class="week-top"><span class="week-number">WEEK ${String(w.n).padStart(2,'0')}</span><span class="badge ${w.n>20?'optional':''}">${w.n>20?'OPTIONAL':p===100?'COMPLETE':w.n===currentWeek()?'CURRENT':phaseNames[Math.min(4,Math.floor((w.n-1)/4))]}</span></div><h3>${esc(titles[w.n-1])}</h3><p>${esc(w.o)}</p><div class="progress"><i style="width:${p}%"></i></div><small>${dateRange(w.n)} · ${p}% complete</small></button>`}
function overview(){let cw=data.weeks[currentWeek()-1],pre=data.weeks.slice(0,20),complete=pre.filter(w=>percent(w)===100).length,next=pre.find(w=>percent(w)<100)||pre[19];return `<div class="hero"><div><span class="eyebrow">FROM DATA ENGINEER TO DATA SCIENTIST</span><h2>Your 240-point data science journey starts here.</h2><p>Twenty focused weeks before Semester One 2027. Build statistics, machine learning and research habits while keeping your engineering edge and preparing for your assigned bridge.</p></div><div class="hero-actions"><a class="btn light" href="#today">Open today's view →</a><a class="btn ghost" style="color:#fff;border-color:#8ecbbb" href="#week-${next.n}">Continue week ${next.n}</a><a class="btn ghost" style="color:#fff;border-color:#8ecbbb" href="#practice">Practice problems</a></div></div><div class="stats-grid"><div class="stat-card"><span>Current streak</span><strong>${calcStreak()}🔥</strong><small>Longest: ${calcLongestStreak()} days</small></div><div class="stat-card"><span>Current week</span><strong>${currentWeek()}</strong><small>${dateRange(currentWeek())}</small></div><div class="stat-card"><span>Weekly target</span><strong>${esc(state.hours)}h</strong><small>Adjust in settings</small></div><div class="stat-card"><span>Weeks completed</span><strong>${complete}/20</strong><small>240-point preparation</small></div></div><div class="two-col"><section class="panel"><span class="eyebrow">THIS WEEK</span><h3 style="font-size:21px;margin:8px 0">${esc(titles[cw.n-1])}</h3><p>${esc(cw.o)}</p><div class="focus-list">${cw.f.slice(0,4).map(([tag,text])=>`<div class="focus-row"><b>${esc(tag)}</b><span>${esc(text.slice(0,88))}${text.length>88?'…':''}</span></div>`).join('')}</div><a class="btn small" style="margin-top:18px" href="#week-${cw.n}">Open week →</a></section><section class="panel"><span class="eyebrow">YOUR STUDY RULES</span><h3 style="font-size:21px;margin:8px 0">Depth over checklist volume</h3><p>Finish the three exact mission steps, one practice task and the weekly deliverable. The topic atlas holds every roadmap node for exploration; it is not a requirement to master each one before starting university.</p><div class="output-box"><b>Example split · 12 hours/week</b><p>${currentWeek()<=12?"5h statistics and ML · 3h project · 2h data engineering · 1h SQL/Python drills · 1h review.":"5h statistics and ML · 3h project · 1h data engineering · 1h R · 1h AI evaluation · 1h review."} Scale this to your weekly target in Settings.</p></div></section></div><div class="guide-cta"><a class="btn ghost" href="#skills">Check your skill evidence →</a><a class="btn ghost" href="#career">Build your NZ portfolio →</a></div><div class="section-head"><div><h2>Up next</h2><p>Keep momentum with one deliverable each week.</p></div><a class="link" href="#plan">Full plan →</a></div><div class="week-grid">${pre.slice(Math.max(0,currentWeek()-1),Math.max(0,currentWeek()-1)+3).map(weekCard).join('')}</div>`}

/* ---------- Today view ---------- */
function todayView(){
  const k=todayKey(),w=data.weeks[currentWeek()-1];
  const allTasks=tasks(w);
  const nextTasks=allTasks.filter(t=>!state.done[t.id]).slice(0,5);
  const streak=calcStreak(),weekPct=percent(w);
  const week=last7Days().map(d=>{const act=state.activity[d];const mins=act?.minutes||0;const active=act&&(mins>0||(act.tasks&&act.tasks.length)||act.missions>0);return {d,mins,active}});
  const maxMins=Math.max(30,...week.map(x=>x.mins));
  return `<div class="today-head"><div><span class="eyebrow">TODAY · ${new Date().toLocaleDateString('en-NZ',{weekday:'long',day:'numeric',month:'long'})}</span><h2>${esc(titles[currentWeek()-1])}</h2><p class="muted">Week ${currentWeek()} · ${dateRange(currentWeek())} · ${weekPct}% complete</p></div><div class="today-streak"><span class="streak-fire">${streak>0?'🔥':'·'}</span><div><strong>${streak}</strong><small>day streak</small></div></div></div>
  <div class="today-grid">
    <section class="panel focus-panel">
      <div class="focus-head"><span class="eyebrow">FOCUS TIMER · <span id="timer-preset-label">25</span> MIN</span><button class="link" id="timer-preset-toggle">Switch preset</button></div>
      <div class="timer-display" id="timer-display">25:00</div>
      <div class="timer-controls"><button class="btn" id="timer-start">Start</button><button class="btn ghost small" id="timer-reset">Reset</button></div>
      <p class="tiny muted">Work on one task. When the timer ends, the session is logged automatically.</p>
      <div class="timer-session-row"><label class="form-row" style="margin:0"><span>Log minutes manually</span><input type="number" id="manual-minutes" min="5" max="300" placeholder="e.g. 45"></label><button class="btn small" id="log-minutes">Log</button></div>
    </section>
    <section class="panel">
      <span class="eyebrow">TODAY'S NEXT ACTIONS</span>
      ${nextTasks.length?`<h3 style="margin:16px 0 10px;font-size:14px">Roadmap topics</h3><div class="task-list">${nextTasks.map(t=>`<label class="task"><input type="checkbox" data-task="${t.id}" ${state.done[t.id]?'checked':''}><span><b>${esc(t.tag)}</b>${esc(t.text.slice(0,110))}${t.text.length>110?'…':''}</span></label>`).join('')}</div>`:''}
      ${(!nextTasks.length)?'<p class="tiny muted" style="margin-top:10px">All tasks for this week are complete. Open the <a class="link" href="#plan">weekly plan</a> to review or move ahead.</p>':''}
      <a class="btn small" style="margin-top:14px" href="#week-${currentWeek()}">Open full week →</a>
    </section>
    <section class="panel">
      <span class="eyebrow">LAST 7 DAYS</span>
      <div class="activity-bars">${week.map(({d,mins,active})=>`<div class="activity-bar ${active?'active':''}"><div class="activity-bar-fill" style="height:${Math.max(4,Math.round(mins/maxMins*100))}%"></div><span class="activity-bar-label">${d.slice(-2)}</span><small>${mins}m</small></div>`).join('')}</div>
      <p class="tiny muted">Each bar shows logged minutes. Time manually or with the focus timer.</p>
    </section>
    <section class="panel">
      <span class="eyebrow">QUICK LINKS</span>
      <div class="quick-link-grid">
        <a href="#practice" class="quick-link"><b>✎ Practice Hub</b><small>SQL · Python · R · DSA</small></a>
        <a href="#atlas" class="quick-link"><b>◎ Topic atlas</b><small>593 checkpoints</small></a>
        <a href="#skills" class="quick-link"><b>◫ Skill map</b><small>Rate and evidence</small></a>
        <a href="#week-${currentWeek()}" class="quick-link"><b>▤ This week</b><small>Deliverable and notes</small></a>
      </div>
    </section>
  </div>`;
}

const practiceTracks=[
{key:'sql',name:'SQL',when:'Weeks 1–12, then maintenance',cadence:'2–3 problems per week · 45–60 minutes',goal:'Start with SELECT, joins and grouping; move to CTEs and window functions.',resources:[['START HERE','LeetCode SQL 50','https://leetcode.com/studyplan/top-sql-50/','Follow the basic-to-intermediate sequence.'],['MORE REPETITIONS','HackerRank SQL','https://www.hackerrank.com/domains/sql','Filter by joins, aggregation and advanced select.'],['INTERVIEW PRACTICE','DataLemur SQL','https://datalemur.com/questions','Try one timed analytics question after the basics.']]},
{key:'python',name:'Python',when:'Weeks 1–12; use in projects throughout',cadence:'2 small exercises per week · 30–45 minutes',goal:'Work in Python first, then reuse the same ideas in notebooks and data projects.',resources:[['START HERE','Exercism Python','https://exercism.org/tracks/python/exercises','Short coding exercises with tests and feedback.'],['DATA SCIENCE','Kaggle Python','https://www.kaggle.com/learn/python','Complete the interactive lesson exercises.'],['DATA WRANGLING','Kaggle Pandas','https://www.kaggle.com/learn/pandas','Practise selecting, grouping and joining real data.']]},
{key:'r',name:'R',when:'Weeks 13–20, or earlier for a statistics bridge',cadence:'1–2 exercises per week · 30–45 minutes',goal:'Get comfortable with vectors and functions, then practise tidy data analysis.',resources:[['START HERE','Exercism R','https://exercism.org/tracks/r/exercises/','Work through the language exercises in order.'],['APPLIED R','R for Data Science','https://r4ds.hadley.nz/','Do the end-of-chapter exercises with your own dataset.'],['MODELLING','Tidy Modeling with R','https://www.tmwr.org/','Run the worked examples after your R foundations.']]},
{key:'dsa',name:'DSA',when:'Optional for the statistics bridge and interview prep',cadence:'1–2 problems per week · 45–60 minutes if relevant',goal:'Follow the complete A2Z sequence with its video lessons and direct practice problems.',resources:dsaTrackers.map(t=>['SOURCE SHEET',t.name,t.url,t.desc])}
];
const skillNames=Object.fromEntries(skillLanes.flatMap(l=>l.skills).map(s=>[s.id,s.name]));
function impactTags(skills,goal,goalHref='#degree'){
 return `<div class="impact-tags">${skills.map(id=>`<a class="impact-tag skill-impact" href="#skills" data-skill-jump="${esc(id)}" title="Open this skill in the Skill map">Skill · ${esc(skillNames[id])}</a>`).join('')}<a class="impact-tag goal-impact" href="${esc(goalHref)}" title="See how this supports your plan">Goal · ${esc(goal)}</a></div>`
}
function focusImpact(tag,focus){
 const t=focus.toLowerCase();let skills=[];
 if(tag==='R')skills=['r'];
 else if(tag==='AI')skills=[/evaluat|safety|failure/.test(t)?'ai-eval':'rag'];
 else if(tag==='DE')skills=[/quality|lineage|ingest|reproducib|backfill/.test(t)?'quality':/sql/.test(t)&&!/spark|distributed|parquet|stream/.test(t)?'sql':'spark'];
 else if(tag==='STATS')skills=[/metrics|calibration|model comparison|backtest/.test(t)?'evaluation':'stats'];
 else if(tag==='ML')skills=[/pytorch|backprop|neural|deep learning|sgd|adam/.test(t)?'dl':/llm|nlp|transformer|embedding/.test(t)?'rag':/backtest|calibration|evaluation|failure/.test(t)?'evaluation':'ml'];
 else if(tag==='PRJ')skills=[/rag|agent|ai /.test(t)?'rag':/pipeline|ingest|data quality/.test(t)?'quality':/forecast|backtest|model|evaluation/.test(t)?'evaluation':'ml'];
 const goal=tag==='PRJ'||tag==='AI'?'Portfolio proof':tag==='DE'?'Engineering portfolio':tag==='R'?'Statistics bridge':'Master’s readiness';
 return impactTags(skills,goal,tag==='PRJ'||tag==='AI'||tag==='DE'?'#career':'#degree')
}
const dsaItems=dsaSheet.flatMap(step=>step.sections.flatMap(section=>section.items));
function dsaCount(){return dsaItems.filter(item=>state.dsaDone[item.id]).length}
function dsaLink(label,url){return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:''}
function dsaRow(item){
 const practice=[dsaLink('LeetCode',item.leetcode),dsaLink('GFG',item.gfg),item.other?dsaLink(item.other[0],item.other[1]):''].join('');
 return `<article class="dsa-row ${state.dsaDone[item.id]?'done':''}"><div class="dsa-row-head"><div><span class="dsa-difficulty ${esc((item.difficulty||'').toLowerCase())}">${esc(item.difficulty||'Concept')}</span><h4>${esc(item.title)}</h4></div><label class="dsa-check"><input type="checkbox" data-dsa-task="${esc(item.id)}" ${state.dsaDone[item.id]?'checked':''}><span>Done</span></label></div><div class="dsa-row-links">${item.video?dsaLink('▶ Watch lesson',item.video):'<span class="dsa-unavailable">Video not listed</span>'}${item.read?dsaLink('Read article',item.read):''}${practice||'<span class="dsa-unavailable">Practice link not listed</span>'}</div></article>`
}
function dsaView(){return `<div class="dsa-intro"><span class="eyebrow">COMPLETE A2Z PRACTICE PATH</span><h2>Learn, then solve each problem</h2><p>Work through the 18 A2Z steps in order. Watch its YouTube lesson when one is listed, then open a direct LeetCode or GFG problem from Traverses. Some foundation exercises use Code360. Mark a problem done after solving it.</p>${impactTags(['algorithms'],'CS bridge / interviews')}<div class="dsa-source-links"><a href="https://bugaddr.github.io/a2z_old_sheet/" target="_blank" rel="noopener noreferrer">A2Z source sheet ↗</a><a href="https://traverses.tech/problems" target="_blank" rel="noopener noreferrer">Traverses problem list ↗</a></div></div><div class="dsa-controls"><label>Step<select id="dsa-step">${dsaSheet.map(step=>`<option value="${step.step}">Step ${step.step} · ${esc(step.title)} (${step.sections.reduce((n,section)=>n+section.items.length,0)})</option>`).join('')}</select></label><label>Find a problem<input id="dsa-search" type="search" placeholder="Search all 477 problems…" autocomplete="off"></label><div class="dsa-progress" data-dsa-progress>${dsaCount()} / ${dsaItems.length} done</div></div><div id="dsa-results"></div>`}
function renderDsa(){
 const target=$('#dsa-results');if(!target)return;
 const query=($('#dsa-search')?.value||'').trim().toLowerCase(),selected=Number($('#dsa-step')?.value||1);
 let shown=0;
 target.innerHTML=dsaSheet.filter(step=>query||step.step===selected).map(step=>{
  const sections=step.sections.map((section,index)=>{
   const items=section.items.filter(item=>!query||`${step.title} ${section.title} ${item.title}`.toLowerCase().includes(query));
   if(!items.length)return '';
   shown+=items.length;
   const done=items.filter(item=>state.dsaDone[item.id]).length;
   return `<details class="dsa-section" ${query||index===0?'open':''}><summary><span>${esc(section.title)}</span><small data-dsa-section-count>${done}/${items.length} done</small></summary><div class="dsa-list">${items.map(dsaRow).join('')}</div></details>`
  }).join('');
  return sections?`<section class="dsa-step"><h3>Step ${step.step} · ${esc(step.title)}</h3>${sections}</section>`:''
 }).join('')||'<p class="dsa-empty">No problems match your search.</p>';
 const count=$('#dsa-result-count');if(count)count.textContent=`${shown} problems shown`;
}
function practice(){return `<div class="practice-intro"><span class="eyebrow">HANDS-ON PRACTICE</span><h2>Pick one track and solve real problems.</h2><p>These links take you directly to exercises. Keep them within your existing weekly study hours: SQL and Python support the first 12 weeks; R becomes more important in weeks 13–20. DSA is optional unless your course bridge or interviews call for it.</p><a class="btn small" href="#today">Back to today →</a></div><div class="practice-grid">${practiceTracks.map(t=>`<section class="practice-card" id="practice-${t.key}"><div class="practice-card-head"><span class="eyebrow">${esc(t.when)}</span><h3>${esc(t.name)}</h3><p>${esc(t.goal)}</p><span class="practice-cadence">${esc(t.cadence)}</span></div><div class="practice-links">${t.resources.map(([type,name,url,description])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer"><span class="eyebrow">${esc(type)}</span><b>${esc(name)} ↗</b><small>${esc(description)}</small></a>`).join('')}</div>${t.key==='dsa'?'<div class="dsa-extra"><a class="btn" href="#dsa">Open complete A2Z sheet →</a></div>':''}</section>`).join('')}</div><p class="tiny muted" style="margin-top:18px">Use the exercise sites to track problem completion. Record useful solutions or links in your weekly notes here.</p>`}
function missionPanel(n){const m=missions[n-1];if(!m)return '';let count=m.steps.filter((_,i)=>state.missions[`${n}-${i}`]).length;return `<section class="panel mission-panel" id="weekly-mission"><span class="eyebrow">EXACT WEEKLY MISSION</span><h3 style="margin-top:8px">Do these three things <span class="mission-count" data-mission-count="${n}">${count}/3 done</span></h3><div class="task-list">${m.steps.map((step,i)=>`<label class="task mission-step"><input type="checkbox" data-mission="${n}-${i}" ${state.missions[`${n}-${i}`]?'checked':''}><span><b>STEP ${i+1}</b>${esc(step)}</span></label>`).join('')}</div><div class="mission-proof"><b>Done when</b><p>${esc(m.proof)}</p></div><label class="form-row mission-evidence"><span>Link to your notebook, repo or write-up</span><input type="url" data-week-evidence="${n}" value="${esc(state.weekEvidence[n]||'')}" placeholder="https://github.com/..." autocomplete="off"></label><p class="tiny muted">Your link and checks are saved in this browser. Back them up in Settings if you switch devices.</p></section>`}
function updateSkillEvidenceCount(){let node=document.querySelector('[data-skill-evidence-count]');if(node){let all=skillLanes.flatMap(l=>l.skills),done=all.filter(x=>Number(state.skillLevels[x.id])===3&&state.skillEvidence[x.id]).length;node.textContent=done+' of '+all.length+' skills have strong evidence.'}}
function skillMap(){let all=skillLanes.flatMap(l=>l.skills),done=all.filter(x=>Number(state.skillLevels[x.id])===3&&state.skillEvidence[x.id]).length;return `<div class="section-head" style="margin-top:0"><div><h2>Skill map</h2><p>Rate what you can demonstrate, then save a link to evidence. A rating is a self-assessment, not a certification.</p></div></div><div class="callout"><b data-skill-evidence-count>${done} of ${all.length} skills have strong evidence.</b> Use 0 = not started, 1 = learning, 2 = can do with notes, 3 = can explain and ship. Prioritise statistics and model evaluation before adding more AI tools.</div>${skillLanes.map(l=>`<section class="skill-lane"><div class="section-head"><div><h2>${esc(l.name)}</h2><p>${esc(l.description)}</p></div></div><div class="skill-grid">${l.skills.map(x=>`<article class="skill-card" id="skill-${esc(x.id)}"><span class="eyebrow">WEEKS ${esc(x.week)}</span><h3>${esc(x.name)}</h3><p><b>Show:</b> ${esc(x.evidence)}</p><div class="skill-actions"><a href="${esc(x.learn)}" target="_blank" rel="noopener noreferrer">Learn ↗</a><a href="${esc(x.practice)}" target="_blank" rel="noopener noreferrer">Practise ↗</a></div><label class="form-row"><span>Current level</span><select data-skill-level="${esc(x.id)}"><option value="0" ${!state.skillLevels[x.id]?'selected':''}>0 · Not started</option><option value="1" ${state.skillLevels[x.id]==1?'selected':''}>1 · Learning</option><option value="2" ${state.skillLevels[x.id]==2?'selected':''}>2 · Can do with notes</option><option value="3" ${state.skillLevels[x.id]==3?'selected':''}>3 · Can explain and ship</option></select></label><label class="form-row"><span>Evidence URL</span><input type="url" data-skill-evidence="${esc(x.id)}" value="${esc(state.skillEvidence[x.id]||'')}" placeholder="https://github.com/..." autocomplete="off"></label></article>`).join('')}</div></section>`).join('')}`}
function career(){return `<div class="practice-intro"><span class="eyebrow">CAREER PATH · NEW ZEALAND</span><h2>Build proof for three related roles.</h2><p>Your data engineering experience is a strong base. Add statistical reasoning, responsible model evaluation and one evaluated AI application. The projects below are designed to produce evidence you can discuss in interviews during or after the degree.</p><a class="btn small" href="#skills">Review skill gaps →</a></div><div class="career-role-grid"><article class="course-card"><span class="course-code">ROLE 01</span><h3>Data engineer / analytics engineer</h3><p>Show reliable pipelines, SQL, Python, cloud data and measured performance. Your existing experience should be visible in project decisions.</p><a class="link" href="https://www.seek.co.nz/data-engineer-jobs" target="_blank" rel="noopener noreferrer">Browse current NZ roles ↗</a></article><article class="course-card"><span class="course-code">ROLE 02</span><h3>Data scientist</h3><p>Show statistical inference, experiments, honest validation, R/Python and clear communication. Auckland coursework and the forecasting study support this path.</p><a class="link" href="https://www.seek.co.nz/data-scientist-jobs" target="_blank" rel="noopener noreferrer">Browse current NZ roles ↗</a></article><article class="course-card"><span class="course-code">ROLE 03</span><h3>ML / AI engineer</h3><p>Show deployable models, retrieval, evaluation, testing and safe operation. One evaluated system is more persuasive than a collection of demos.</p><a class="link" href="https://www.seek.co.nz/machine-learning-engineer-jobs" target="_blank" rel="noopener noreferrer">Browse current NZ roles ↗</a></article></div><div class="section-head"><div><h2>Portfolio build tracker</h2><p>Use public or permitted datasets. Save your project link and tick each review criterion when the proof is visible.</p></div></div><div class="portfolio-grid">${portfolioProjects.map(project=>{let count=project.criteria.filter((_,i)=>state.portfolio[`${project.id}-${i}`]).length;return `<section class="panel portfolio-card"><span class="eyebrow">${esc(project.role)} · ${esc(project.weeks)}</span><h3>${esc(project.name)}</h3><p>${esc(project.brief)}</p><span class="practice-cadence" data-portfolio-count="${project.id}">${count}/${project.criteria.length} criteria</span><div class="task-list">${project.criteria.map((c,i)=>`<label class="task"><input type="checkbox" data-portfolio="${project.id}-${i}" ${state.portfolio[`${project.id}-${i}`]?'checked':''}><span>${esc(c)}</span></label>`).join('')}</div><label class="form-row"><span>Project URL</span><input type="url" data-portfolio-link="${project.id}" value="${esc(state.portfolioLinks[project.id]||'')}" placeholder="https://github.com/..." autocomplete="off"></label></section>`}).join('')}</div><section class="panel" style="margin-top:18px"><span class="eyebrow">NZ ROLE SIGNALS · CHECKED OCT 2026</span><h3 style="margin-top:8px">What employers are asking for</h3><p>Recent New Zealand postings emphasise advanced SQL and Python, applied modelling, end-to-end delivery, privacy, and communicating results. Some research and analyst roles also explicitly ask for R and causal or forecasting work. These are examples, not a complete or permanent job-market survey.</p><p><a class="link" href="https://jobs.govt.nz/jobtools/jncustomsearch.viewFullSingle?in_jnCounter=226704024&in_orderby=dateinput+desc&in_organid=16563" target="_blank" rel="noopener noreferrer">ACC data scientist example ↗</a> · <a class="link" href="https://jobs.govt.nz/jobs/NZ-1951809" target="_blank" rel="noopener noreferrer">MSD forecasting example ↗</a> · <a class="link" href="https://jobs.lever.co/tracksuit-limited/8a3a1a5a-c713-4fea-8b43-2180a46d855b" target="_blank" rel="noopener noreferrer">Tracksuit data scientist example ↗</a></p><p class="tiny muted">Role links may expire. Re-check current listings and work eligibility before applying.</p></section>`}
function plan(){return `<div class="section-head" style="margin-top:0"><div><h2>20-week preparation path</h2><p>Start date ${new Date(state.start+'T12:00:00').toLocaleDateString('en-NZ',{day:'numeric',month:'long',year:'numeric'})}. Weeks 21–24 are optional extensions for deeper roadmap coverage.</p></div></div><div class="toolbar" id="plan-filters"><button class="chip active" data-filter="core">Core 20 weeks</button><button class="chip" data-filter="all">All 24 weeks</button><button class="chip" data-filter="incomplete">Incomplete</button></div><div class="week-grid" id="week-grid">${data.weeks.slice(0,20).map(weekCard).join('')}</div>`}
